function switchStore(obj) {
    var storeParam = obj.value ? 'store/' + obj.value + '/' : '';
    if (obj.switchParams) {
        storeParam += obj.switchParams;
    }
        setLocation('http://dockerized-magento.local/index.php/admin/dashboard/index/' + storeParam);
    }

